package com.dixitdada.journalApp.controller; import com.dixitdada.journalApp.api.response.WeatherResponse; import com.dixitdada.journalApp.service.WeatherService; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/weather") @RequiredArgsConstructor public class WeatherController { private final WeatherService w; @GetMapping public WeatherResponse current(@RequestParam double lat,@RequestParam double lon){return w.current(lat,lon);} }